type PFx = { vault: { records: RiskOutput[] }; compatibility: { records: RiskOutput[] } };
const FX = fixtures as unknown as { partners: Record<string, PFx> };
const V1_SHARED = FX.partners.V1A.compatibility.records[0];
const V3_RESIDUAL = FX.partners.V3A.vault.records.find((r) => r.scenario === "discordant" && r.status === "ok") as RiskOutput;
const V4_MISSING = FX.partners.V4B.vault.records[0];

function Section({ id, title, children }: { id: string; title: string; children: ReactNode }) {
  return (
    <section aria-labelledby={`ds-${id}`} className="space-y-4 border-t border-line pt-8" data-testid={`ds-${id}`}>
      <h2 id={`ds-${id}`} className="text-2xl font-semibold">
        {title}
      </h2>
      {children}
    </section>
  );
}
function Row({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="grid gap-2 md:grid-cols-[10rem_1fr] md:items-center">
      <p className="text-sm font-semibold text-ink-2">{label}</p>
      <div className="flex flex-wrap items-center gap-3">{children}</div>
    </div>
  );
}

